"""Nari tab spec v1.0 acceptance tests (NT-1..28, MB-1..18, R-1..6) + AA / 44px sweep and screenshots.
Usage: python3 tests/nari_tab.py [url] [shots_dir]"""
import sys, json, re, os
from playwright.sync_api import sync_playwright
U = sys.argv[1] if len(sys.argv) > 1 else 'http://localhost:8851/platform-app.html'
SH = sys.argv[2] if len(sys.argv) > 2 else '/workspace/hana-shots/nari-tab'
os.makedirs(SH, exist_ok=True)
R = {}; E = []
def ok(k, c, d=''):
  if k in R: k = k + '#' + str(sum(1 for x in R if x.split('#')[0] == k) + 1)
  R[k] = [bool(c), d]
CONTRAST = """() => { const lum = c => { const m = c.match(/[\\d.]+/g).map(Number); const f = v => { v /= 255; return v <= .03928 ? v / 12.92 : Math.pow((v + .055) / 1.055, 2.4); }; return .2126 * f(m[0]) + .7152 * f(m[1]) + .0722 * f(m[2]); };
  const bgOf = el => { while (el) { const b = getComputedStyle(el).backgroundColor; const a = b.match(/[\\d.]+/g).map(Number); if (a.length < 4 || a[3] > .9) return b; el = el.parentElement; } return 'rgb(247,241,234)'; };
  const bad = []; const els = [...document.querySelectorAll('#view *, .sheet *, #tabs *')].filter(e => e.offsetParent && !e.closest('.vh') && [...e.childNodes].some(n => n.nodeType === 3 && n.textContent.trim()));
  for (const e of els) { const cs = getComputedStyle(e); if (e.closest('[disabled]')) continue; const l1 = lum(cs.color), l2 = lum(bgOf(e)); const r = (Math.max(l1, l2) + .05) / (Math.min(l1, l2) + .05); const big = parseFloat(cs.fontSize) >= 24 || (parseFloat(cs.fontSize) >= 18.66 && +cs.fontWeight >= 700); if (r < (big ? 3 : 4.5)) bad.push([e.textContent.trim().slice(0, 30), r.toFixed(2)]); }
  const small = [...document.querySelectorAll('#view button, #view a, .sheet button, .sheet textarea, #tabs button, #top button')].filter(e => e.offsetParent && !e.closest('.vh')).map(e => [e, e.getBoundingClientRect()]).filter(([e, r]) => r.height < 43.5 || r.width < 43.5).map(([e, r]) => [e.dataset.act || e.className, (e.innerText || '').slice(0, 20), Math.round(r.width), Math.round(r.height)]);
  return { bad, small, hscroll: document.documentElement.scrollWidth > innerWidth }; }"""
with sync_playwright() as p:
  b = p.chromium.launch()
  def page(q='', lang=None, w=390, keep=False):
    pg = b.new_page(viewport={'width': w, 'height': 844}); pg.on('pageerror', lambda e: E.append(str(e))); pg.on('console', lambda m: E.append(m.text) if m.type == 'error' else None)
    pg.goto(U + q)
    if not keep: pg.evaluate("()=>localStorage.clear()"); pg.goto(U + q)
    pg.wait_for_timeout(120)
    if lang: pg.evaluate(f"()=>{{setLang('{lang}');render()}}")
    return pg
  J = lambda pg, js: pg.evaluate(js)
  def dismiss_toast(pg):
    pg.evaluate("()=>{const t=document.getElementById('toast'); if(t){t.hidden=true;t.classList.remove('win')} if(typeof closeSheet==='function')closeSheet()}")
    pg.wait_for_timeout(30)
  view = lambda pg: pg.inner_text('#view')
  def send(pg, q): pg.evaluate("q=>__plat.chatSend('cici',q)", q); pg.wait_for_timeout(30)
  def nmsgs(pg): return J(pg, "CH.cici.msgs.filter(m=>m.who==='n').map(m=>({t:m.text,chips:(m.chips||[]).map(c=>c.label),confirm:!!m.confirm,care:!!m.care,kind:m.kind||null}))")
  # ---------------- 9.1 Nari tab ----------------
  pg = page()
  tabs = J(pg, "[...document.querySelectorAll('#tabs button')].map(b=>[b.dataset.v,b.innerText.trim(),b.querySelector('svg').innerHTML.includes('M12 9.5')])")
  ok('NT-1 4 tabs, Nari 3rd with nari icon, no Book/Ask', [t[0] for t in tabs] == ['home', 'discover', 'cici', 'you'] and tabs[2][2] and not any(t[0] in ('book', 'ask') for t in tabs), tabs)
  ok('R-6 no pre-seeded thread', J(pg, "CH.cici.msgs.length") == 0)
  ok('R-5 KO default in KR', J(pg, "L") == 'ko')
  pg.click('[data-act=tab][data-v=cici]'); v = view(pg)
  ok('NT-10 empty: nariHello + 3 chips + Book again, no time chips', '미나님, 안녕하세요. Cici예요.' in v and pg.locator('#view [data-act=qbook]').count() == 1 and pg.locator('#view [data-act=nagain]').count() >= 3 and not re.search(r'\b\d\d:\d\d\b', v), v[:200])
  ok('NT-13 KO chip copy exact', J(pg, "[...document.querySelectorAll('#view .chips:not(.slim) [data-from=cici]')].map(x=>x.innerText)") == ['수업 예약', '질문하기', '내 예약'] and 'First time' not in v)
  ok('NT-12 KO tab labels + Nari aria-label + one aria-current', [t[1] for t in J(pg, "[...document.querySelectorAll('#tabs button')].map(b=>[0,b.innerText.trim()])")] == ['홈', '둘러보기', 'Cici', '나'] and J(pg, "document.querySelector('#tabs [data-v=cici]').getAttribute('aria-label')") == 'Cici, 예약하거나 물어보기' and J(pg, "[...document.querySelectorAll('#tabs [aria-current=page]')].map(b=>b.dataset.v)") == ['cici'])
  ok('NT-28 no top-level phone icon in Nari header', J(pg, "!document.querySelector('#view > .row [data-act=call], #top [data-act=call], #view > .row [data-act=callstore]')"))
  ok('NT-28 / A7 voice demo cut from MVP (no overflow call entry)', J(pg, "!document.querySelector('[data-act=nmore],[data-act=calldemo],[data-act=call]')"))
  # NT-23 ask chip
  pg.click('#view [data-act=qask]'); m = nmsgs(pg)
  ok('NT-23 Ask a question → askPrompt, input focused, no booking chip', m[-1]['t'] == '네, 무엇이 궁금하세요?' and not m[-1]['chips'] and not m[-1]['confirm'] and J(pg, "document.activeElement.id") == 'in-cici', m[-1])
  send(pg, '처음인데 바레 혼자 가도 괜찮아요?'); m = nmsgs(pg)
  ok('NT-23/R-1 first-timer question answered first', m[-1]['t'].startswith('네') and not m[-1]['confirm'] and J(pg, "CH.cici.msgs[CH.cici.msgs.length-1].faq") == 1, m[-1])
  ok('NT-14 returning thread (polish r2: quick chips only on the empty state): no repeated chip row, input docked', J(pg, "(()=>!document.querySelector('#view .chips.slim') && !document.querySelector('#view [data-act=qbook]') && !!document.querySelector('#view .dock form.chatbox'))()"))
  ok('NT-24 calendar icon "내 예약" in header', J(pg, "document.querySelector('#view [data-act=mybk][data-from=cici]').getAttribute('aria-label')") == '내 예약')
  pg.click('#view > .row [data-act=mybk]'); ok('NT-24 icon opens My bookings', J(pg, "ST.page") == 'bookings' and '내 예약' in pg.inner_text('#top'))
  ok('NT-12 no aria-current while a page overlay is open', J(pg, "document.querySelectorAll('#tabs [aria-current]').length") == 0)
  pg.click('#top [data-act=back]'); ok('NT-20/NT-24 Back from My bookings → Nari thread kept', J(pg, "ST.tab") == 'cici' and J(pg, "ST.page") is None and J(pg, "CH.cici.msgs.length") >= 4)
  pg.close()
  # NT-2 scrolled to latest + not auto-focused
  pg = page(); J(pg, "()=>{ for(let i=0;i<14;i++){ __plat.chatSend('cici','what should I bring to pickleball?'); } go('tab:home') }")
  pg.click('[data-act=tab][data-v=cici]'); pg.wait_for_timeout(150)
  ok('NT-2 opens scrolled to latest, input not auto-focused', J(pg, "(()=>{const th=document.querySelector('#th-cici');const r=th.lastElementChild.getBoundingClientRect();return r.top < innerHeight && r.bottom > 0})()") and J(pg, "document.activeElement.id") != 'in-cici')
  pg.close()
  # NT-4 / NT-15 typed path + inline confirm (KO)
  pg = page(); pg.click('[data-act=tab][data-v=cici]'); send(pg, '바레 내일 오전'); m = nmsgs(pg)
  ok('NT-4 "바레 내일 오전" → time chips', any(re.match(r'\d\d:\d\d', c) for c in m[-1]['chips']), m[-1])
  n0 = J(pg, "__plat.B.length"); pg.locator('#th-cici .mchips .chip').first.click(); pg.wait_for_timeout(60)
  card = pg.inner_text('#th-cici .mcard')
  ok('NT-4 confirm card: ₩ price + store cancel policy', '₩' in card and ('무료 취소' in card or '스튜디오' in card) and '늦은 취소' in card, card)
  ok('NT-25 Call {store} on the confirm card (KO; short label, full aria)', 'Capsule Barre에 전화' in J(pg, "document.querySelector('#th-cici .mcard [data-act=callstore]')?.getAttribute('aria-label')||''") and J(pg, "document.querySelector('#th-cici .mcard [data-act=callstore]').innerText.trim()") == '전화')
  pg.locator('#th-cici [data-act=chatbook]').last.click(); pg.wait_for_timeout(60)
  ok('NT-15 typed: slot chip + Book = 2 taps → booked', J(pg, "__plat.B.length") == n0 + 1)
  nb = J(pg, "__plat.B[__plat.B.length-1].id")
  ok('NT-4 booking posted in thread and listed in My bookings → Upcoming', '예약됨' in view(pg) and J(pg, f"__plat.bkUpcoming().some(b=>b.id==={nb})"))
  J(pg, "closeSheet()"); dismiss_toast(pg); y0 = J(pg, "scrollY"); pg.locator('#th-cici [data-act=managebk]').last.click(); s5 = pg.locator('.sheet').count(); pg.click('.sheet [data-act=close]'); y1 = J(pg, "scrollY")
  ok('NT-5 Manage from the thread card → sheet; closing keeps scroll', s5 == 1 and abs(y0 - y1) < 2 and J(pg, "ST.tab") == 'cici', [y0, y1])
  # NT-15 Book again path
  n0 = J(pg, "__plat.B.length"); pg.evaluate("go('tab:home')"); pg.click('[data-act=tab][data-v=cici]')
  J(pg, "CH.cici.msgs=[];render()"); dismiss_toast(pg); pg.click('#view [data-act=nagain][data-i="1"]'); dismiss_toast(pg); pg.locator('#th-cici [data-act=chatbook]').last.click(force=True); pg.wait_for_timeout(60)
  ok('NT-15 Book again: chip → Book = 2 taps', J(pg, "__plat.B.length") == n0 + 1)
  J(pg, "CH.cici.msgs=[];render()"); dismiss_toast(pg); pg.click('#view [data-act=nagain][data-i="0"]'); alts = nmsgs(pg)[-1]['chips']
  ok('NT-15 pre-picked slot is editable (other times + full sheet)', len(alts) >= 2 and '다른 시간' in alts, alts)
  pg.locator('#th-cici .mchips .chip').last.click(); ok('NT-4 detail opens the existing openBook() sheet', pg.locator('.sheet [data-act=slot], .sheet [data-act=classpick]').count() > 0); pg.evaluate("closeSheet()")
  pg.close()
  # NT-3 store scope
  pg = page(); J(pg, "go('store:capsule')"); pg.click('#view [data-act=go][data-v="cici:store:capsule"]')
  ok('NT-3 Book here → removable store chip', pg.locator('#view [data-act=unscope]').count() == 1 and 'Capsule Barre' in pg.inner_text('#view [data-act=unscope]'))
  send(pg, '내일 오전'); ok('NT-3 replies scoped to the store', J(pg, "(CH.cici.draft||{}).store") == 'capsule', J(pg, "CH.cici.draft"))
  pg.click('#view [data-act=unscope]'); ok('NT-3 chip removable', J(pg, "CH.cici.scope") is None and pg.locator('#view [data-act=unscope]').count() == 0)
  pg.close()
  # NT-6 inbox bell
  pg = page(); badge = J(pg, "(document.querySelector('#top [data-act=inbox] .badge')||{}).textContent"); pg.click('#top [data-act=inbox]'); nv = view(pg)
  ok('NT-6 bell shows unread count; Inbox is separate with store names', badge and int(badge) > 0 and J(pg, "ST.page") == 'notif' and 'Capsule Barre' in nv and J(pg, "CH.cici.msgs.length") == 0, badge)
  pg.close()
  # NT-7 legacy openers / saved state
  pg = page(); J(pg, "go('tab:book')"); m = nmsgs(pg)
  ok('NT-7 tab:book → Nari, Book chip state', J(pg, "ST.tab") == 'cici' and m and m[-1]['kind'] == 'bookPrompt' and len(m[-1]['chips']) >= 3)
  J(pg, "go('tab:book')"); ok('NT-7 no duplicate prompt', len(nmsgs(pg)) == 1)
  J(pg, "go('tab:home')"); J(pg, "go('tab:ask')"); ok('NT-7 tab:ask → Nari, Ask state (focus, no new booking prompt)', J(pg, "ST.tab") == 'cici' and len(nmsgs(pg)) == 1 and J(pg, "document.activeElement.id") == 'in-cici')
  J(pg, "()=>{ST.tab='book';render()}"); ok('NT-7 raw ST.tab "book" renders Nari', J(pg, "ST.tab") == 'cici' and 'Cici' in pg.inner_text('#top'))
  pg.close()
  pg = page(); J(pg, "()=>{localStorage.setItem('nari.tab','ask');localStorage.removeItem('nari.migrated')}"); pg.goto(U); pg.wait_for_timeout(120)
  ok('NT-7 saved ST.tab "ask" → Nari, no blank screen', J(pg, "ST.tab") == 'cici' and len(view(pg)) > 40 and not E, E[-2:])
  pg.close()
  # NT-8 unread dot
  pg = page(); J(pg, "()=>{const [s,v,o]=__plat.AGAIN[1];openBook(s,v,Object.assign({},o))}"); pg.locator('.sheet [data-act=slot]').first.click(); pg.locator('.sheet [data-act=dobook]').click(); pg.evaluate("closeSheet()")
  dot = J(pg, "!!document.querySelector('#tabs [data-v=cici] .tdot')"); txt = pg.inner_text('#tabs [data-v=cici]')
  ok('NT-8 unread Nari reply → dot, never a number', dot and not re.search(r'\d', txt) and '새 답장' in J(pg, "document.querySelector('#tabs [data-v=cici]').getAttribute('aria-label')"))
  ok('§5 sheet booking adds a confirm bubble to CH.cici', any(x.get('bk') for x in J(pg, "CH.cici.msgs")))
  pg.click('[data-act=tab][data-v=cici]'); ok('NT-8 dot clears when Nari is opened', not J(pg, "!!document.querySelector('#tabs [data-v=cici] .tdot')"))
  pg.close()
  pg = page(); J(pg, "()=>{__plat.INBOX.unshift({s:'capsule',text:'20% off this week!',when:'Now',unread:true,promo:true});render()}")
  ok('NT-8 promo / marketing only → no dot', not J(pg, "!!document.querySelector('#tabs .tdot')")); pg.close()
  # NT-9 migration
  pg = page(); J(pg, """()=>{localStorage.removeItem('nari.migrated');localStorage.setItem('nari.chat.book',JSON.stringify([{who:'me',text:'barre tomorrow',t:3},{who:'n',text:'Which time?',t:4}]));
    localStorage.setItem('nari.chat.ask',JSON.stringify([{who:'n',text:"Hi Mina, I'm Nari. I can book at any of your places, move a booking, or answer simple questions about them.",t:1},{who:'me',text:'parking?',t:2},{who:'n',text:'Motorbike parking at the front.',t:5}]))}""")
  pg.goto(U); pg.wait_for_timeout(120); ms = J(pg, "CH.cici.msgs.map(m=>m.div?'DIV':m.text)")
  ok('NT-9 merged by timestamp, Ask greeting dropped, one divider', ms == ['parking?', 'barre tomorrow', 'Which time?', 'Motorbike parking at the front.', 'DIV'] and pg.locator('#view .ndiv').count() == 0, ms)
  J(pg, "go('tab:cici')"); ok('NT-9 divider shows once in the thread', pg.locator('#view .ndiv').count() == 1)
  pg.goto(U); pg.wait_for_timeout(120); ok('NT-9 reload does not migrate again (saved thread kept, one divider)', J(pg, "CH.cici.msgs.length") == 5 and J(pg, "CH.cici.msgs.filter(m=>m.div).length") == 1 and J(pg, "localStorage.getItem('nari.migrated')") == '1' and J(pg, "localStorage.getItem('nari.chat.ask')") is None)
  ok('NT-9 pure merge keeps every message once', len(J(pg, "__plat.migrateThreads([{who:'me',text:'a',t:2}],[{who:'n',text:'b',t:1},{who:'me',text:'a',t:2}])")) == 3)
  pg.close()
  # NT-11 / NT-18 / NT-19 / NT-24 / NT-27 / R-3 crisis gating
  for lang, q, copy in [('en', 'i want to end my life', 'glad you told me'), ('vi', 'tôi muốn tự tử', 'mừng vì bạn'), ('ko', '죽고 싶어요', '이야기해 주셔서')]:
    pg = page('', lang); J(pg, "go('tab:cici')"); send(pg, 'what should I bring to pickleball?'); e0 = J(pg, "__plat.EVT.length"); send(pg, q); v = view(pg)
    hidden = J(pg, "['.chips.slim','[data-act=nagain]','[data-act=qbook]','[data-act=mybk]','[data-act=callstore]','[data-act=chatbook]','[href^=tel]'].filter(s=>document.querySelector('#view '+s))")
    ok(f'R-3/NT-18 crisis turn hides chips, Book again, confirm, calendar, Call ({lang})', copy in v and not hidden and not re.search(r'\d{3}', nmsgs(pg)[-1]['t']) and not re.search(r'point|điểm|포인트|voucher|reward|리워드', nmsgs(pg)[-1]['t'], re.I), hidden)
    ev = J(pg, f"__plat.EVT.slice({e0})")
    ok(f'NT-11 analytics: only safety_turn, no text ({lang})', [x['e'] for x in ev] == ['safety_turn'] and q not in json.dumps(ev, ensure_ascii=False), ev)
    send(pg, 'ok'); J(pg, "go('tab:home')"); J(pg, "go('tab:book')"); J(pg, "go('tab:cici')")
    hidden2 = J(pg, "['.chips.slim','[data-act=mybk]','[data-act=callstore]'].filter(s=>document.querySelector('#view '+s))")
    ok(f'NT-18/NT-19 AC5: still hidden after ok + redirects, no booking prompt ({lang})', not hidden2 and not any(m['kind'] == 'bookPrompt' for m in nmsgs(pg)), hidden2)
    send(pg, {'en': 'barre tomorrow morning', 'vi': 'barre sáng mai', 'ko': '바레 내일 오전'}[lang])
    ok(f'NT-18 chips return when the member asks for a booking ({lang})', pg.locator('#view .chips.slim').count() == 0 and pg.locator('#view > .row [data-act=mybk]').count() == 1)
    pg.close()
  pg = page('', 'ko'); J(pg, "go('tab:cici')"); send(pg, '수업 중에 가슴이 아프고 어지러워요'); v = view(pg); last = nmsgs(pg)[-1]
  ok('R-2/NT-27 urgent: stop + doctor/instructor, no number/tel/booking/points', ('멈추' in v or '중단' in v) and not re.search(r'\d{3}', last['t']) and pg.locator('#view [href^=tel], #view [data-act=callstore], #view .chips.slim, #view [data-act=mybk]').count() == 0 and not last['chips'] and not re.search(r'포인트|예약', last['t']), last)
  ok('NT-11 urgent logged as safety_turn{urgent} only', J(pg, "__plat.EVT.filter(e=>e.e==='safety_turn').map(e=>e.type)") == ['urgent'])
  pg.close()
  pg = page('', 'en'); J(pg, "go('tab:cici')"); ok('R-2 no persistent red bar; small Need help? under the input', pg.locator('#view .sosbar, #view .redbar').count() == 0 and J(pg, "(()=>{const f=document.querySelector('#view form.chatbox'),h=document.querySelector('#view .helplink');return !!h&&!!(f.compareDocumentPosition(h)&Node.DOCUMENT_POSITION_FOLLOWING)})()"))
  pg.click('#view .helplink'); hs = pg.inner_text('.sheet')
