  pg.close()
  # NT-17
  pg = page(); J(pg, "go('cici:book')"); ok('NT-17 Book opener → Cici Book chip state', J(pg, "ST.tab") == 'cici' and nmsgs(pg)[-1]['kind'] == 'bookPrompt')
  J(pg, "go('cici:ask:처음인데 바레 혼자 가도 괜찮아요?')"); ok('NT-17 "Ask Nari" opener with a question → sent as the member message', J(pg, "CH.cici.msgs.filter(m=>m.who==='me').pop().text") == '처음인데 바레 혼자 가도 괜찮아요?')
